// Claude's review tests for A43 batch 1 in the browser. agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, newProject } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

async function open(): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [newProject('p1', fixture.origin)] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

/** Stops the extension's service worker, as Chrome does after 30 s idle. */
async function stopWorker(panel: Page) {
  const cdp = await panel.context().newCDPSession(panel);
  await cdp.send('ServiceWorker.enable');
  await cdp.send('ServiceWorker.stopAllWorkers');
  await cdp.detach();
  await panel.waitForTimeout(500);
}

test('#2 the Log keeps its rows and keeps updating after the worker stops, twice', async () => {
  const { page, panel } = await open();
  try {
    const rows = panel.getByTestId('log-row');
    await page.evaluate(async () => (await fetch('/api/goals?n=1')).text());
    await expect(rows).toHaveCount(1);

    await stopWorker(panel);
    await page.evaluate(async () => (await fetch('/api/goals?n=2')).text());
    await expect(rows).toHaveCount(2);

    await stopWorker(panel);
    await page.evaluate(async () => (await fetch('/api/goals?n=3')).text());
    await expect(rows).toHaveCount(3);
    // No duplicates after reconnecting.
    await panel.waitForTimeout(500);
    await expect(rows).toHaveCount(3);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('#4 a forged log row with bad base64 does not break the panel', async () => {
  const { page, panel } = await open();
  try {
    await page.evaluate(() => {
      window.postMessage({
        source: 'wemock-page', type: 'log',
        entry: { method: 'GET', url: 'http://x.test/forged', status: 200, responseHeaders: {}, responseBody: '%%%', responseEncoding: 'base64', truncated: false, durationMs: 1, badge: 'real', startedAt: 1 },
      }, '*');
    });
    const row = panel.getByTestId('log-row').filter({ hasText: '/forged' });
    await expect(row).toHaveCount(1);
    await row.click();
    await expect(panel.getByTestId('detail-url')).toContainText('/forged');
    // The panel still works after it.
    await page.evaluate(async () => (await fetch('/api/goals')).text());
    await expect(panel.getByTestId('log-row')).toHaveCount(2);
    await panel.getByTestId('tab-mocks').click();
    await expect(panel.getByTestId('mock-new')).toBeVisible();
  } finally {
    await panel.close();
    await page.close();
  }
});
